          "claim": "attractions pod restart counter was 0 in the normal period and climbed to 2–6 during the incident."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_status_code, count(*) n, avg(duration)/1e6 avg_ms FROM abnormal_traces WHERE service_name = 'frontend' AND span_name LIKE 'attractions.%' GROUP BY 1,2 ORDER BY 1,2",
